data.minimal_example:
final openpay = OpenpayBBVA(
  merchantId: 'YOUR_MERCHANT_ID',
  publicApiKey: 'YOUR_PUBLIC_API_KEY',
  productionMode: false,
  country: Country.MX,
);

final token = await openpay.getCardToken(
  CardInformation(
    holderName: 'John Doe',
    cardNumber: '4111111111111111',
    expirationMonth: '12',
    expirationYear: '25',
    cvv2: '123',
  ),
);
